BEGIN;

-- ---------- 1. 清理旧业务数据 ----------
DELETE FROM operation_log;
DELETE FROM follow_up;
DELETE FROM opportunity;
DELETE FROM contact;
DELETE FROM customer;
DELETE FROM sys_user_role WHERE user_id NOT IN (SELECT id FROM sys_user WHERE username = 'admin');
DELETE FROM sys_user WHERE username <> 'admin';

-- ---------- 2. 演示用户 ----------
ON CONFLICT (username) DO NOTHING;

SELECT u.id, r.id FROM sys_user u, sys_role r
WHERE (u.username, r.role_code) IN (
    ('manager1', 'MANAGER'), ('sales1', 'SALES'), ('sales2', 'SALES'),
    ('sales3', 'SALES'), ('guest1', 'GUEST')
)
ON CONFLICT (user_id, role_id) DO NOTHING;

